styles.h1:
font-size: 32px;
font-weight: 800;
color: var(--pop-text);
margin-top: 20px;
margin-bottom: 20px;
text-transform: uppercase;
letter-spacing: 1px;
text-shadow: 3px 3px 0 var(--pop-primary);
position: relative;
padding-bottom: 10px;

styles.h2:
font-size: 24px;
font-weight: 700;
color: var(--pop-text);
margin-top: 24px;
margin-bottom: 16px;
background-color: var(--pop-accent2);
padding: 4px 10px;
transform: rotate(-2deg);

styles.h3:
font-size: 20px;
font-weight: 700;
color: var(--pop-text);
margin-top: 20px;
margin-bottom: 12px;
background-color: var(--pop-accent3);
padding: 4px 10px;
border-radius: 4px;

styles.h6:
color: #6b8c42;
margin-top: 1.2em;
margin-bottom: 0.5em;
font-weight: 700;
border-bottom: 1px solid #d4d9c9;
padding-bottom: 0.3em;

styles.strong:
color: var(--pop-primary);
background-color: var(--pop-white);
padding: 0 5px;
border: 3px solid var(--pop-border);
display: inline-block;
transform: rotate(-2deg);

styles.a:
color: var(--pop-primary);
text-decoration: none;
font-weight: 700;
border-bottom: 3px solid var(--pop-border);
padding: 0 3px;
transition: all 0.3s ease;

styles.ul:
background-color: rgba(255, 255, 255, 0.7);
padding: 15px;
border: 2px solid var(--pop-border);
border-radius: 8px;

styles.ol:
background-color: var(--coil-list-bg);
padding: 15px;
border: 1px dashed var(--coil-border);
border-radius: 8px;

styles.blockquote:
border-left: 8px solid var(--pop-primary);
color: var(--pop-text);
font-style: italic;
font-weight: 600;
background-color: rgba(var(--pop-primary-rgb), 0.1);
border-radius: 0 8px 8px 0;
position: relative;

styles.code:
font-family: "SFMono-Regular", Consolas, "Liberation Mono", Menlo, monospace;
background: rgba(0, 0, 0, 0.04);
padding: 2px 6px;
border-radius: 4px;
font-size: 14px;
color: #fa2c19;
border-bottom: 2px solid rgba(250, 44, 25, 0.1);

styles.pre:
background-color: var(--pop-code-bg);
border-radius: 8px;
padding: 15px;
font-family: "SFMono-Regular", Consolas, "Liberation Mono", Menlo, monospace;
font-size: 14px;
overflow-x: auto;
color: var(--pop-white);
border: 2px solid var(--pop-primary);
box-shadow: 5px 5px 0 var(--pop-accent2);

styles.hr:
border: 0;
height: 6px;
background: repeating-linear-gradient(
  45deg,
  var(--pop-primary),
  var(--pop-primary) 10px,
  var(--pop-text) 10px,
  var(--pop-text) 20px
);
margin: 25px 0;
border-radius: 3px;

styles.img:
max-width: 100%;
border: 5px solid var(--pop-border);
border-radius: 0;
box-shadow: 8px 8px 0 var(--pop-primary);
transform: rotate(-1deg);

styles.table:
border-collapse: separate;
border-spacing: 0;
width: 100%;
margin: 20px 0;
background-color: rgba(255, 255, 255, 0.7);
border: 3px solid var(--pop-border);
border-radius: 8px;
overflow: hidden;
box-shadow: 5px 5px 0 var(--pop-primary);

styles.th:
background-color: var(--pop-code-bg);
color: var(--pop-white);
padding: 12px;
text-align: left;
font-weight: 700;
text-transform: uppercase;
letter-spacing: 1px;

styles.td:
border-bottom: 2px solid var(--pop-border);
padding: 10px;
position: relative;
